-- ADR-0813: confronta campos operacionais com a fotografia da decisão.
create or replace function pcm.sso_avaliar_decisoes_impacto(p_cliente_id uuid,p_plano_id uuid,p_expected_plano integer)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_previa jsonb;v_origem uuid;v_rascunho uuid;v_total integer;v_ausentes integer;v_obsoletas integer;v_reconciliar integer;v_fontes_incompletas integer;v_divergentes integer;
begin
 if not coalesce((select habilitado from pcm.sso_avaliacao_impacto_revisao_gate where id),false) or not coalesce((select habilitado from pcm.sso_decisao_impacto_revisao_gate where id),false) then raise exception 'avaliacao_impacto_bloqueada' using errcode='55000';end if;
 if auth.uid() is null or config.sso_autorizar_acao('plano.gerir',p_cliente_id) is distinct from true or not exists(select 1 from pcm.planos_manutencao where id=p_plano_id and cliente_id=p_cliente_id) then raise exception 'sem_acesso' using errcode='42501';end if;
 v_previa:=pcm.sso_previa_revisao_revisionada(p_plano_id,p_expected_plano,1,null);v_origem:=(v_previa->>'versaoAnteriorId')::uuid;v_rascunho:=(v_previa->>'versaoRascunhoId')::uuid;
 with itens as (
  select o.id,o.versao_id,o.rotina_id,to_jsonb(o) preparada_atual,d.request_id,d.revisao_plano,d.decisao,d.fotografia,v.ocorrencia_legada_id,
   (select count(*) from pcm.ordens_servico os where os.ocorrencia_preventiva_id=v.ocorrencia_legada_id and os.client_id is distinct from p_cliente_id and os.deleted_at is null) divergentes,
   (select count(*) from pcm.ordens_servico os where os.ocorrencia_preventiva_id=v.ocorrencia_legada_id and os.client_id=p_cliente_id and os.deleted_at is null) os_count,
   (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'status',s.status,'updatedAt',s.updated_at) order by s.id),'[]'::jsonb) from (select os.id,os.status,os.updated_at from pcm.ordens_servico os where os.ocorrencia_preventiva_id=v.ocorrencia_legada_id and os.client_id=p_cliente_id and os.deleted_at is null order by os.id limit 101) s) os_atuais
  from pcm.ocorrencias_rotina_preparadas o left join pcm.ocorrencias_rotina_vinculos v on v.ocorrencia_preparada_id=o.id
  left join lateral (select x.* from pcm.sso_decisoes_impacto_ocorrencia x where x.rascunho_id=v_rascunho and x.preparada_id=o.id order by x.revisao desc limit 1) d on true
  where o.plano_id=p_plano_id and o.versao_id=v_origem
 ) select count(*),count(*) filter(where request_id is null),count(*) filter(where request_id is not null and (revisao_plano<>p_expected_plano or jsonb_build_object('id',(fotografia->'preparada')->'id','plano_id',(fotografia->'preparada')->'plano_id','versao_id',(fotografia->'preparada')->'versao_id','rotina_id',(fotografia->'preparada')->'rotina_id','rotina_logica_id',(fotografia->'preparada')->'rotina_logica_id','alvo_tipo',(fotografia->'preparada')->'alvo_tipo','alvo_id',(fotografia->'preparada')->'alvo_id','ciclo',(fotografia->'preparada')->'ciclo','vencimento_original',(fotografia->'preparada')->'vencimento_original','tolerancia_antes',(fotografia->'preparada')->'tolerancia_antes','tolerancia_depois',(fotografia->'preparada')->'tolerancia_depois') is distinct from jsonb_build_object('id',preparada_atual->'id','plano_id',preparada_atual->'plano_id','versao_id',preparada_atual->'versao_id','rotina_id',preparada_atual->'rotina_id','rotina_logica_id',preparada_atual->'rotina_logica_id','alvo_tipo',preparada_atual->'alvo_tipo','alvo_id',preparada_atual->'alvo_id','ciclo',preparada_atual->'ciclo','vencimento_original',preparada_atual->'vencimento_original','tolerancia_antes',preparada_atual->'tolerancia_antes','tolerancia_depois',preparada_atual->'tolerancia_depois') or fotografia->'os' is distinct from os_atuais or fotografia->>'legadaId' is distinct from ocorrencia_legada_id::text)),count(*) filter(where decisao='exige_reconciliacao'),count(*) filter(where ocorrencia_legada_id is null or os_count>100),count(*) filter(where divergentes>0)
 into v_total,v_ausentes,v_obsoletas,v_reconciliar,v_fontes_incompletas,v_divergentes from itens;
 return jsonb_build_object('revisaoPlano',p_expected_plano,'versaoOrigemId',v_origem,'rascunhoId',v_rascunho,'ocorrenciasCalendarioObservadas',v_total,'decisoesAusentes',v_ausentes,'decisoesObsoletas',v_obsoletas,'exigemReconciliacao',v_reconciliar,'fontesIndividuaisIncompletas',v_fontes_incompletas,'comOsClienteDivergente',v_divergentes,'coberturaVisitasELegadoIndeterminada',true,'impactoIntegralComprovado',false,'aprovacaoAutorizada',false);
end; $$;
